const fs = require('fs');
const path = require('path');
const item = $input.first().json;
const lipsyncPath = path.join(item.project_root, 'lipsync', `${item.chapter_id}_lipsync.json`);
if (!fs.existsSync(lipsyncPath)) {
  return [{ json: { ...item, lipsync_path: null, lipsync_error: 'Rhubarb output missing' } }];
}
const raw = JSON.parse(fs.readFileSync(lipsyncPath, 'utf-8'));
const speaking = [];
const cues = raw.mouthCues || [];
let segStart = null;
for (const c of cues) {
  if (c.value !== 'X') {
    if (segStart === null) segStart = c.start;
  } else {
    if (segStart !== null) { speaking.push({ start: segStart, end: c.start, mouth: 'speaking' }); segStart = null; }
  }
}
if (segStart !== null) speaking.push({ start: segStart, end: cues[cues.length-1].end || segStart+0.1, mouth: 'speaking' });
const refined = path.join(item.project_root, 'lipsync', `${item.chapter_id}_lipsync.json`);
fs.writeFileSync(refined, JSON.stringify(speaking, null, 2), 'utf-8');
return [{ json: { ...item, lipsync_path: refined.replace(/\\/g, '/'), speaking_segments: speaking.length } }];

